#!/bin/sh
# Repairs Gatus endpoint ConfigMaps generated by Kyverno (gatus-internal/gatus-external)
# whose trigger Ingress was recreated (UID changed) or deleted. Kyverno does not update
# such ConfigMaps anymore, so annotation changes on the Ingress are silently ignored.
#   - stale:  Ingress exists with a different UID -> delete ConfigMap, retrigger Kyverno
#   - orphan: Ingress no longer exists           -> delete ConfigMap
# Set DRY_RUN=true to only report.
set -eu

DRY_RUN="${DRY_RUN:-false}"
WAIT_SECONDS="${WAIT_SECONDS:-60}"
RETRIGGER_ANNOTATION="gatus-ep-reconciler/retrigger"

tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT

# Abort on API errors: an empty Ingress list would mark every ConfigMap as orphaned.
kubectl get ingress --all-namespaces -o json > "$tmp/ingresses.json"
kubectl get configmap --all-namespaces \
  -l 'gatus.io/enabled=true,app.kubernetes.io/managed-by=kyverno,generate.kyverno.io/trigger-kind=Ingress' \
  -o json > "$tmp/configmaps.json"

jq -r --slurpfile ing "$tmp/ingresses.json" '
  ($ing[0].items | map({key: "\(.metadata.namespace)/\(.metadata.name)", value: .metadata.uid}) | from_entries) as $uids
  | .items[]
  | .metadata.labels as $l
  | ($uids["\($l["generate.kyverno.io/trigger-namespace"])/\($l["generate.kyverno.io/trigger-name"])"]) as $current
  | (if $current == null then "orphan"
     elif $current != $l["generate.kyverno.io/trigger-uid"] then "stale"
     else empty end) as $state
  | "\($state) \(.metadata.namespace) \(.metadata.name) \($l["generate.kyverno.io/trigger-namespace"]) \($l["generate.kyverno.io/trigger-name"])"
' "$tmp/configmaps.json" > "$tmp/actions.txt"

if [ ! -s "$tmp/actions.txt" ]; then
  echo "All Gatus endpoint ConfigMaps match their Ingress."
  exit 0
fi

failed=0
while read -r state cm_ns cm_name ing_ns ing_name; do
  echo "${state}: ConfigMap ${cm_ns}/${cm_name} (Ingress ${ing_ns}/${ing_name})"
  if [ "$DRY_RUN" = "true" ]; then
    continue
  fi

  kubectl -n "$cm_ns" delete configmap "$cm_name"
  if [ "$state" = "orphan" ]; then
    continue
  fi

  # Any Ingress UPDATE makes Kyverno re-run the generating policy.
  kubectl -n "$ing_ns" annotate ingress "$ing_name" "${RETRIGGER_ANNOTATION}=$(date +%s)" --overwrite >/dev/null
  waited=0
  until kubectl -n "$cm_ns" get configmap "$cm_name" >/dev/null 2>&1; do
    if [ "$waited" -ge "$WAIT_SECONDS" ]; then
      break
    fi
    sleep 5
    waited=$((waited + 5))
  done
  kubectl -n "$ing_ns" annotate ingress "$ing_name" "${RETRIGGER_ANNOTATION}-" >/dev/null

  if kubectl -n "$cm_ns" get configmap "$cm_name" >/dev/null 2>&1; then
    echo "  regenerated by Kyverno"
  else
    echo "  ERROR: ConfigMap not regenerated within ${WAIT_SECONDS}s" >&2
    failed=1
  fi
done < "$tmp/actions.txt"

exit "$failed"
